def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for i in range(h):
        for j in range(w):
            if grid[i][j] != 0 or (i, j) in seen:
                continue
            stack = [(i, j)]
            seen.add((i, j))
            component = []
            while stack:
                x, y = stack.pop()
                component.append((x, y))
                for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        nx, ny = x + dx, y + dy
                        if (0 <= nx < h and 0 <= ny < w and
                                grid[nx][ny] == 0 and (nx, ny) not in seen):
                            seen.add((nx, ny))
                            stack.append((nx, ny))
            if len(component) > 1:
                for x, y in component:
                    out[x][y] = 8
    return out
